   observed fixed desktop rail. Keep the native layout and hit areas. */
nav,
[role="navigation"] {
  background: linear-gradient(to right, rgba(4,23,14,.88), rgba(6,31,19,.85) 58%, rgba(7,38,25,.82)) !important;
  color: #d9ffe6 !important;
