  box-shadow: inset -1px 0 0 rgba(0,255,102,.65), 7px 0 17px -7px rgba(0,255,102,.55), 13px 0 28px -13px rgba(0,255,102,.35) !important;
}

nav a[href],
[role="navigation"] a[href],
[role="navigation"] [role="button"] {
  border-radius: 9px !important;
}

nav a[href]:hover,
[role="navigation"] a[href]:hover,
[role="navigation"] [role="button"]:hover {
  box-shadow: inset 0 0 0 1px rgba(45,255,118,.42) !important;
}

nav a[aria-current="page"],
[role="navigation"] a[aria-current="page"] {
  box-shadow: inset 3px 0 0 #00ff66 !important;
}

